<script lang="ts">
import { defineComponent, ref, computed, watch } from 'vue';
import { LocalStorage } from 'quasar';
import { supportApiService } from 'src/services';
import {
  getSlowCalls,
  clearSlowCalls,
  getFailedCalls,
  clearFailedCalls,
} from 'src/utils/performanceStore';
import type { SlowCall, FailedCall } from 'src/utils/performanceStore';
import { computeSlowCallsByType } from 'src/utils/slowCallsByType';
import { notify } from 'src/components/notifications/notify';
import {
  collectSnapshot,
  getErrorBuffer,
  getConsoleBuffer,
} from 'src/boot/debugCollector';
import type { DebugSnapshot } from 'src/boot/debugCollector';
import { stripBannedTerms, redactUrlSecrets } from 'src/utils/debugRedactor';
import { formatSupportTicketErrorMessage } from 'src/utils/supportTicketErrorMessage';

interface Vitals {
  ttfb: number | null;
  domLoad: number | null;
  fullLoad: number | null;
}

function collectVitals(): Vitals {
  try {
    const nav = performance.getEntriesByType('navigation')[0] as
      | PerformanceNavigationTiming
      | undefined;
    if (!nav) return { ttfb: null, domLoad: null, fullLoad: null };
    return {
      ttfb: Math.round(nav.responseStart - nav.requestStart),
      domLoad: Math.round(nav.domContentLoadedEventEnd - nav.startTime),
      fullLoad: Math.round(nav.loadEventEnd - nav.startTime),
    };
  } catch {
    return { ttfb: null, domLoad: null, fullLoad: null };
  }
}

function esc(s: string): string {
  // Escapes both element- and attribute-context metacharacters. The ticket
  // body interpolates values into href="…"/style="…" attributes, so quotes
  // MUST be escaped to prevent attribute-breakout HTML injection in Zammad.
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function fmtVital(val: number | null, unit = 'ms'): string {
  if (val === null) return '<span style="color:#999">N/A</span>';
  return `<strong>${val}${unit}</strong>`;
}

function buildTicketBody(
  slowCalls: SlowCall[],
  failedCalls: FailedCall[],
  vitals: Vitals,
  debugSnapshot: DebugSnapshot | null,
  notes: string,
): string {
  const h: string[] = [];

  h.push('<h2>Performance Report</h2>');
  h.push(
    `<p><strong>URL:</strong> ${esc(redactUrlSecrets(window.location.href))}<br>`,
  );
  h.push(`<strong>Time:</strong> ${new Date().toLocaleString()}`);
  if (debugSnapshot?.trace_summary?.primary_trace_id) {
    h.push(
      `<br><strong>Trace ID:</strong> <code>${esc(debugSnapshot.trace_summary.primary_trace_id)}</code>`,
    );
  }
  h.push('</p>');

  // --- Failed API Calls ---
  h.push('<h3>Failed API Calls (4xx / 5xx / success=false)</h3>');
  if (failedCalls.length === 0) {
    h.push(
      '<p style="color:#999">No failed calls recorded since app start.</p>',
    );
  } else {
    h.push(
      '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px;width:100%">',
    );
    h.push(
      '<tr style="background:#ffebee"><th>Method</th><th>URL</th><th>Status</th><th>Duration</th><th>Backend</th><th>Time</th></tr>',
    );
    failedCalls.forEach((c) => {
      const statusColor = c.softFailure
        ? '#7b1fa2'
        : c.status >= 500
          ? '#e53935'
          : '#f57c00';
      const st = c.serverTiming;
      const backend = st
        ? [
            st.total && `Server:${st.total.toFixed(0)}ms`,
            st.db && `DB:${st.db.toFixed(0)}ms`,
            st.cache && `Cache:${st.cache.toFixed(0)}ms`,
          ]
            .filter(Boolean)
            .join(' ')
        : '—';
      h.push(`<tr>`);
      h.push(`<td><strong>${esc(c.method)}</strong></td>`);
      h.push(
        `<td style="word-break:break-all;max-width:300px;font-size:12px">${esc(redactUrlSecrets(c.url))}${c.traceId ? ` <a href="https://grafana.docbits.com/explore?traceId=${esc(c.traceId)}" style="font-size:10px">[trace]</a>` : ''}${c.supportTraceId ? `<br><span style="font-size:10px;color:#1565c0">docbits_trace_id: ${esc(c.supportTraceId)}</span>` : ''}${c.searchTraceId ? `<br><span style="font-size:10px;color:#00796b">search_trace_id: ${esc(c.searchTraceId)}</span>` : ''}</td>`,
      );
      h.push(
        `<td style="color:${statusColor};text-align:right"><strong>${c.softFailure ? '200 ✗' : c.status}</strong>${c.softFailure && c.message ? `<br><span style="font-size:10px">${esc(c.message)}</span>` : ''}</td>`,
      );
      h.push(
        `<td style="text-align:right">${(c.duration / 1000).toFixed(2)}s</td>`,
      );
      h.push(`<td style="font-size:11px;color:#666">${backend}</td>`);
      h.push(
        `<td style="color:#666">${new Date(c.timestamp).toLocaleTimeString()}</td>`,
      );
      h.push('</tr>');
    });
    h.push('</table>');
  }

  // --- Slow queries by type ---
  const byTypeRows = computeSlowCallsByType(slowCalls);
  if (byTypeRows.length > 0) {
    h.push('<h3>Slow queries by type</h3>');
    h.push(
      '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px;width:100%">',
    );
    h.push(
      '<tr style="background:#e3f2fd"><th>Type</th><th>Count</th><th>Avg (ms)</th><th>p95 (ms)</th></tr>',
    );
    for (const r of byTypeRows) {
      h.push(
        `<tr><td>${esc(r.type)}</td><td style="text-align:right">${r.count}</td><td style="text-align:right">${r.avgMs}</td><td style="text-align:right">${r.p95Ms}</td></tr>`,
      );
    }
    h.push('</table>');
  }

  // --- Slow API Calls ---
  h.push('<h3>Slow API Calls (&ge; 2s)</h3>');
  if (slowCalls.length === 0) {
    h.push('<p style="color:#999">No slow calls recorded since app start.</p>');
  } else {
    h.push(
      '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px;width:100%">',
    );
    h.push(
      '<tr style="background:#f5f5f5"><th>Method</th><th>URL</th><th>Duration</th><th>Backend</th><th>Status</th><th>Time</th></tr>',
    );
    slowCalls.forEach((c) => {
      const durColor = c.duration >= 5000 ? '#e53935' : '#f57c00';
      const st = c.serverTiming;
      const backend = st
        ? [
            st.total && `Server:${st.total.toFixed(0)}ms`,
            st.db && `DB:${st.db.toFixed(0)}ms`,
            st.cache && `Cache:${st.cache.toFixed(0)}ms`,
          ]
            .filter(Boolean)
            .join(' ')
        : '—';
      h.push(`<tr>`);
      h.push(`<td><strong>${esc(c.method)}</strong></td>`);
      h.push(
        `<td style="word-break:break-all;max-width:300px;font-size:12px">${esc(redactUrlSecrets(c.url))}${c.traceId ? ` <a href="https://grafana.docbits.com/explore?traceId=${esc(c.traceId)}" style="font-size:10px">[trace]</a>` : ''}${c.supportTraceId ? `<br><span style="font-size:10px;color:#1565c0">docbits_trace_id: ${esc(c.supportTraceId)}</span>` : ''}${c.searchTraceId ? `<br><span style="font-size:10px;color:#00796b">search_trace_id: ${esc(c.searchTraceId)}</span>` : ''}</td>`,
      );
      h.push(
        `<td style="color:${durColor};text-align:right"><strong>${(c.duration / 1000).toFixed(2)}s</strong></td>`,
      );
      h.push(`<td style="font-size:11px;color:#666">${backend}</td>`);
      h.push(`<td style="text-align:right">${c.status || '—'}</td>`);
      h.push(
        `<td style="color:#666">${new Date(c.timestamp).toLocaleTimeString()}</td>`,
      );
      h.push('</tr>');
    });
    h.push('</table>');
  }

  // --- Page Load Vitals ---
  h.push('<h3>Page Load Vitals</h3>');
  h.push(
    '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;font-size:13px">',
  );
  h.push(`<tr><td>TTFB</td><td>${fmtVital(vitals.ttfb)}</td></tr>`);
  h.push(`<tr><td>DOM Load</td><td>${fmtVital(vitals.domLoad)}</td></tr>`);
  h.push(`<tr><td>Full Load</td><td>${fmtVital(vitals.fullLoad)}</td></tr>`);
  h.push('</table>');

  // --- Environment ---
  h.push('<h3>Environment</h3>');
  h.push(
    '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px">',
  );
  h.push(`<tr><td>Browser</td><td>${esc(navigator.userAgent)}</td></tr>`);
  const mem = (performance as any).memory;
  if (mem) {
    h.push(
      `<tr><td>JS Heap</td><td>${Math.round(mem.usedJSHeapSize / 1024 / 1024)}MB / ${Math.round(mem.jsHeapSizeLimit / 1024 / 1024)}MB</td></tr>`,
    );
  }
  h.push('</table>');

  // --- Debug Snapshot Summary ---
  if (debugSnapshot) {
    h.push('<h3>Debug Snapshot</h3>');
    h.push(
      '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px">',
    );
    h.push(
      `<tr><td>Trace ID</td><td><code>${esc(String(debugSnapshot.trace_summary?.primary_trace_id || 'N/A'))}</code></td></tr>`,
    );
    h.push(
      `<tr><td>API Calls (slow/error)</td><td><strong>${debugSnapshot.api_calls.length}</strong></td></tr>`,
    );
    h.push(
      `<tr><td>Errors</td><td><strong style="${debugSnapshot.errors.length > 0 ? 'color:#e53935' : ''}">${debugSnapshot.errors.length}</strong></td></tr>`,
    );
    h.push(
      `<tr><td>Console Entries</td><td><strong>${debugSnapshot.console_log.length}</strong></td></tr>`,
    );
    h.push(
      `<tr><td>WebSocket</td><td><strong>${esc(String(debugSnapshot.websocket.state || 'N/A'))}</strong></td></tr>`,
    );
    h.push(
      `<tr><td>Session Duration</td><td>${debugSnapshot.user_context.session_duration_s}s</td></tr>`,
    );
    h.push(
      `<tr><td>Route</td><td>${esc(String(debugSnapshot.user_context.active_route))}</td></tr>`,
    );
    h.push(
      `<tr><td>Org ID</td><td><code>${esc(String(debugSnapshot.user_context.org_id || 'N/A'))}</code></td></tr>`,
    );
    h.push('</table>');

    // --- Service Versions ---
    if (
      debugSnapshot.service_versions &&
      debugSnapshot.service_versions.length > 0
    ) {
      h.push('<h3>Service Versions</h3>');
      h.push(
        '<table border="1" cellpadding="4" cellspacing="0" style="border-collapse:collapse;font-size:12px">',
      );
      h.push(
        '<tr style="background:#f5f5f5"><th>Service</th><th>Version</th><th>Status</th><th>Deployed</th></tr>',
      );
      debugSnapshot.service_versions.forEach((sv) => {
        const statusColor =
          sv.status === 'healthy' || sv.status === 'ok'
            ? '#4caf50'
            : sv.status === 'warning'
              ? '#ff9800'
              : '#999';
        h.push(
          `<tr><td>${esc(sv.app)}</td><td><strong>${esc(sv.version)}</strong></td><td style="color:${statusColor}">${esc(sv.status)}</td><td style="color:#666">${esc(sv.deployment_date)}</td></tr>`,
        );
      });
      h.push('</table>');
    }

    h.push('<p><em>Full debug JSON attached as file.</em></p>');
  }

  // --- Additional Notes ---
  if (notes) {
    h.push('<h3>Additional Notes</h3>');
    h.push(`<p>${esc(notes).replace(/\n/g, '<br>')}</p>`);
  }

  return h.join('\n');
}

export default defineComponent({
  name: 'PerformanceAnalysisDialog',
  props: {
    modelValue: { type: Boolean, required: true },
  },
  emits: ['update:modelValue'],
  setup(props, { emit }) {
    const open = computed({
      get: () => props.modelValue,
      set: (val) => emit('update:modelValue', val),
    });

    const slowCalls = ref<SlowCall[]>([]);
    const failedCalls = ref<FailedCall[]>([]);
    const jsErrors = ref<any[]>([]);
    const jsWarnings = ref<any[]>([]);
    const vitals = ref<Vitals>({ ttfb: null, domLoad: null, fullLoad: null });
    const sending = ref(false);
    const debugSnapshot = ref<DebugSnapshot | null>(null);

    const priorityOptions = [
      { label: 'Very High', value: 'Very High' },
      { label: 'High', value: 'High' },
      { label: 'Medium', value: 'Medium' },
      { label: 'Low', value: 'Low' },
    ];

    const ticket = ref({
      subject: '',
      priority: { label: 'High', value: 'High' },
      message: '',
      email: '',
      fullname: '',
    });

    const debugSnapshotSizeKb = computed(() => {
      if (!debugSnapshot.value) return 0;
      try {
        return Math.round(JSON.stringify(debugSnapshot.value).length / 1024);
      } catch {
        return 0;
      }
    });

    const slowQueriesByType = computed(() =>
      computeSlowCallsByType(slowCalls.value),
    );
    const primaryTraceId = computed(
      () => debugSnapshot.value?.trace_summary?.primary_trace_id || '',
    );

    // Collect data when dialog opens
    watch(open, async (val) => {
      if (!val) return;
      slowCalls.value = getSlowCalls();
      failedCalls.value = getFailedCalls();
      vitals.value = collectVitals();

      // Collect JS errors and console warnings from debug buffers
      jsErrors.value = getErrorBuffer().toArray();
      jsWarnings.value = getConsoleBuffer()
        .toArray()
        .filter((e: any) => e.level === 'warn' || e.level === 'error');

      // Collect debug snapshot
      try {
        debugSnapshot.value = await collectSnapshot();
      } catch {
        debugSnapshot.value = null;
      }

      const pageName =
        window.location.pathname.split('/').filter(Boolean).pop() || 'app';
      ticket.value.subject = `Performance Issue — ${pageName} — ${new Date().toLocaleString()}`;

      try {
        const user = LocalStorage.getItem('user_details') as any;
        if (user) {
          ticket.value.email = user.email || user.username || '';
          ticket.value.fullname =
            `${user.first_name || ''} ${user.last_name || ''}`.trim();
        }
      } catch {}
    });

    function shortenUrl(url: string): string {
      try {
        const u = new URL(url);
        return u.pathname + (u.search ? '?' + u.search.slice(1, 40) + '…' : '');
      } catch {
        return url.length > 60 ? url.slice(0, 60) + '…' : url;
      }
    }

    function formatTime(iso: string): string {
      return new Date(iso).toLocaleTimeString();
    }

    function tempoUrl(traceId: string): string {
      // traceId is server-supplied (x-trace-id header); only allow hex so a
      // crafted value can't break out of the pre-encoded JSON query string.
      if (!/^[0-9a-fA-F]{8,64}$/.test(traceId)) return '#';
      return `https://grafana.docbits.com/explore?orgId=1&left=%7B%22datasource%22:%22tempo%22,%22queries%22:%5B%7B%22queryType%22:%22traceql%22,%22query%22:%22${traceId}%22%7D%5D%7D`;
    }

    function truncate(s: string, max: number): string {
      return s && s.length > max ? s.slice(0, max) + '...' : s || '';
    }

    function vitalColor(val: number | null, warn: number, bad: number): string {
      if (val === null) return '';
      if (val >= bad) return 'text-negative';
      if (val >= warn) return 'text-warning';
      return 'text-positive';
    }

    async function copyDebugData() {
      if (!debugSnapshot.value) return;
      try {
        await navigator.clipboard.writeText(
          JSON.stringify(debugSnapshot.value, null, 2),
        );
        notify.success('Debug data copied to clipboard');
      } catch {
        notify.error('Failed to copy to clipboard');
      }
    }

    async function copyTraceId() {
      if (!primaryTraceId.value) return;
      try {
        await navigator.clipboard.writeText(primaryTraceId.value);
        notify.success('Trace ID copied to clipboard');
      } catch {
        notify.error('Failed to copy trace ID');
      }
    }

    async function sendTicket() {
      if (!ticket.value.email || !ticket.value.email.includes('@')) {
        notify.error('Please enter a valid email address.');
        return;
      }

      sending.value = true;
      try {
        // Strip banned vendor terms from the whole HTML body too — the JSON
        // snapshot is already stripped, but the body also embeds page/call URLs
        // and the user's free-text note.
        const body = stripBannedTerms(
          buildTicketBody(
            slowCalls.value,
            failedCalls.value,
            vitals.value,
            debugSnapshot.value,
            ticket.value.message,
          ),
        ) as string;

        const formData = new FormData();
        formData.append('fullname', ticket.value.fullname);
        formData.append('customer_email', ticket.value.email);
        formData.append('subject', ticket.value.subject);
        formData.append('priority', ticket.value.priority.value);
        formData.append('body', body);

        // Attach debug snapshot as JSON file (field name: 'attachment' per API schema)
        if (debugSnapshot.value) {
          const timestamp = debugSnapshot.value.generated_at
            .replace(/[:.]/g, '-')
            .slice(0, 19);
          const debugBlob = new Blob(
            [JSON.stringify(debugSnapshot.value, null, 2)],
            { type: 'application/json' },
          );
          formData.append(
            'attachment',
            debugBlob,
            `docbits-debug-${timestamp}.json`,
          );
        }

        await supportApiService.create_ticket(formData);
        notify.success('Performance report sent successfully');
        clearSlowCalls();
        clearFailedCalls();
        open.value = false;
      } catch (err: any) {
        console.error(
          '[PerformanceDialog] send ticket failed:',
          err?.response?.data ?? err,
        );
        notify.error(formatSupportTicketErrorMessage(err));
      } finally {
        sending.value = false;
      }
    }

    return {
      open,
      slowCalls,
      failedCalls,
      vitals,
      sending,
      ticket,
      priorityOptions,
      debugSnapshot,
      debugSnapshotSizeKb,
      primaryTraceId,
      slowQueriesByType,
      shortenUrl,
      formatTime,
      tempoUrl,
      truncate,
      vitalColor,
      jsErrors,
      jsWarnings,
      copyDebugData,
      copyTraceId,
      sendTicket,
    };
  },
});
</script>

