import { toBoolPreference } from 'src/utils/preferenceBool';

/**
 * Whether the Workflows item belongs in the side menu.
 *
 * The flag can arrive as the string "0"/"1" (script/SQL writes) as well as a
 * real boolean. A non-empty string like "0" is truthy in JS, so a bare
 * `if (setting)` check would show the menu for a disabled module —
 * toBoolPreference normalises both representations the way the backend does.
 * The builder is admin-only and never shown to supplier users.
 */
export function shouldShowWorkflowMenu(
  workflowBuilderSetting: unknown,
  context: { isSupplier: boolean; isAdmin: boolean },
): boolean {
  if (!toBoolPreference(workflowBuilderSetting)) {
    return false;
  }
  if (context.isSupplier) {
    return false;
  }
  return context.isAdmin;
}
