<template>
  <Icon
    :icon="icon"
    :width="size"
    :height="size"
    :class="iconClass"
  />
</template>

<script lang="ts">
import { defineComponent } from 'vue';


export default defineComponent({
  name: 'NavIcon',
  
  props: {
    icon: {
      type: String,
      required: true,
    },
    isActive: {
      type: Boolean,
      required: true,
    },
    size: {
      type: [Number, String],
      default: 24,
    },
  },
  computed: {
    iconClass(): string {
      return this.isActive
        ? 'nav-icon nav-icon--active'
        : 'nav-icon nav-icon--inactive';
    },
  },
});
</script>

<style lang="scss" scoped>
@import 'src/css/quasar.variables.scss';

.nav-icon {
  display: inline-flex;

  &--active {
    color: $primary;
  }

  &--inactive {
    color: var(--dashboard-gray-activated);
  }
}
</style>
