<template>
  <q-toolbar class="text-white secondary-toolbar">
    <q-toolbar-title>
      <span class="text-weight-bold">{{ $t('service_versions') }}</span>
    </q-toolbar-title>
    <q-btn flat round dense icon="close" v-close-popup />
  </q-toolbar>

  <q-card-section class="scrolle-y versions-scroll-area">
    <!-- Error banner for complete failure (Kong down) -->
    <q-banner v-if="loadError && versionRows.length === 1" class="bg-negative text-white q-mb-md">
      <template v-slot:avatar>
        <q-icon name="warning" />
      </template>
      Failed to load service versions from backend.
      <div class="text-caption q-mt-xs">{{ errorMessage }}</div>
      <template v-slot:action>
        <q-btn flat label="Retry" @click="init()" color="white" />
      </template>
    </q-banner>

    <!-- Metadata for debugging -->
    <q-card-section v-if="metadata" class="q-pa-sm q-mb-sm metadata-section">
      <div class="text-caption">
        <strong>Services:</strong> {{ metadata.successful }}/{{ metadata.total_services }} loaded successfully
        <span v-if="metadata.failed > 0" class="text-negative">
          ({{ metadata.failed }} failed)
        </span>
        <span class="q-ml-md">
          Response time: {{ metadata.elapsed_time?.toFixed(2) }}s
        </span>
      </div>
    </q-card-section>

    <!-- Service versions table -->
    <DocBitsTable
      :rows="versionRows"
      :columns="tableColumns"
      :loading="loading"
      row-key="app"
      table-id="service-versions-table"
      table-class=""
      :features="{
        sorting: true,
        clientSideSort: true,
        filtering: false,
        selection: false,
        pagination: false,
        resizable: false,
      }"
      flat-style
      class="versions-table"
    >
      <!-- Custom cell for app name (no health indicator inline) -->
      <template #body-cell-app="{ row }">
        <span :class="{ 'text-negative': row.failed }">
          {{ getDisplayName(row.app) }}
        </span>
      </template>

      <!-- Custom cell for health status indicator -->
      <template #body-cell-status="{ row }">
        <span v-if="row.health" class="health-indicator cursor-pointer">
          {{ getHealthIcon(row.health.status) }}
          <q-tooltip anchor="center right" self="center left">
            {{ getHealthTooltip(row.health) }}
          </q-tooltip>
        </span>
      </template>

      <!-- Custom cell for version (shows error if failed) -->
      <template #body-cell-version="{ row }">
        <template v-if="!row.failed">
          {{ row.version }}
        </template>
        <template v-else>
          <span class="text-negative">
            <q-icon name="error_outline" size="xs" class="q-mr-xs" />
            {{ row.error || 'Failed to load' }}
          </span>
        </template>
      </template>

      <!-- Custom cell for release channel — shows the release NAME
           (Vesta/Nova), not the raw technical channel value -->
      <template #body-cell-release="{ row }">
        <q-badge
          v-if="row.channel"
          :color="row.channel === 'nova' ? 'deep-orange-7' : 'green-7'"
          :label="getReleaseName(row.channel)"
          class="release-badge"
        />
        <span v-else>-</span>
      </template>

      <!-- Custom cell for deployment date -->
      <template #body-cell-deployed="{ row }">
        <template v-if="!row.failed">
          {{ formatDateAccordingToPreference(row.deployed) }}
        </template>
      </template>
    </DocBitsTable>

    <!-- Retry button for partial failures -->
    <q-card-actions align="right" v-if="metadata && metadata.failed > 0 && !loadError">
      <q-btn flat label="Retry Failed Services" color="primary" @click="init()" />
    </q-card-actions>
  </q-card-section>
</template>

<script lang="ts">
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { appsApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import displayFieldLabel from 'src/utils/displayFieldLabel.js';
import { notify } from 'src/components/notifications/notify';
import { DocBitsTable } from 'src/components/Table';
import type { UnifiedTableColumn } from 'src/components/Table';
import { getReleaseName } from 'src/utils/release-names';

// Release track of the bundle being viewed: the nova build is served under the
// `/nova/` path prefix (publicPath in quasar.config.cjs), vesta at the root —
// so the URL is what identifies the track. The channel a service reports in its
// own payload stays ignored (DOCB-13891).
function currentChannel(): 'nova' | 'vesta' {
  const pathname =
    typeof window !== 'undefined' ? window.location?.pathname || '' : '';
  return /(^|\/)nova(\/|$)/i.test(pathname) ? 'nova' : 'vesta';
}

export interface VersionRow {
  app: string;
  version: string;
  deployed: string;
  failed: boolean;
  error?: string;
  channel?: string;
  health?: { status: string; details?: string; checked_at?: string };
}

// Short display names for services (to fit health indicator)
const SERVICE_DISPLAY_NAMES: Record<string, string> = {
  'auto-accounting-service': 'Auto Accounting',
  'api-service': 'API Service',
  'auth-bridge-service': 'Auth Bridge',
  'barcode-service': 'Barcode Service',
  'docflow-service': 'Docflow Service',
  'docnet-service': 'Docnet Service',
  'email-service': 'Email Service',
  'extraction-service': 'Extraction Service',
  'ftp-service': 'FTP Service',
  'ocr-service': 'OCR Service',
  'operator-service': 'Operator Service',
  'po-match-service': 'PO Match Service',
  'web_app': 'Web App',
};

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, dateUtils, displayFieldLabel],
  props: {
    app_version: {
      type: String,
      default: '',
    },
  },
  components: {
    DocBitsTable,
  },
  data() {
    return {
      loading: ref(false),
      versionList: ref({} as any),
      loadError: ref(false),
      errorMessage: ref(''),
      metadata: ref(null as any),
    };
  },
  mounted: async function () {
    await this.init();
  },
  computed: {
    /**
     * Column definitions for the service versions table
     */
    tableColumns(): UnifiedTableColumn[] {
      return [
        {
          name: 'app',
          label: 'App',
          field: 'app',
          align: 'left',
          sortable: true,
        },
        {
          name: 'status',
          label: '',
          field: (row: VersionRow) => row.health?.status || '',
          align: 'center',
          sortable: false,
          style: 'width: 40px; padding-left: 0; padding-right: 0',
        },
        {
          name: 'version',
          label: this.$t('version'),
          field: 'version',
          align: 'left',
          sortable: true,
        },
        {
          name: 'release',
          label: this.$t('release'),
          field: (row: VersionRow) => row.channel || '',
          align: 'left',
          sortable: true,
        },
        {
          name: 'deployed',
          label: this.$t('deployment_date'),
          field: 'deployed',
          align: 'left',
          sortable: true,
        },
      ];
    },
    /**
     * Transform versionList object to array format for DocBitsTable
     * Sorted alphabetically by app name
     */
    versionRows(): VersionRow[] {
      return Object.entries(this.versionList)
        .map(([key, data]: [string, any]) => ({
          app: key,
          version: data.version || '',
          deployed: data.deployed || '-',
          failed: data.success === false,
          error: data.error,
          channel: currentChannel(),
          health: data.health,
        }))
        .sort((a, b) => a.app.localeCompare(b.app));
    },
  },
  methods: {
    async init() {
      try {
        this.loading = true;
        this.loadError = false;
        this.errorMessage = '';

        // Fetch web_app health from version.json
        const webAppHealth = await this.fetchWebAppHealth();

        const response = await appsApiService.getAllVersions();

        if (!response.success) {
          // Complete failure (Kong down)
          this.loadError = true;
          this.errorMessage = response.error || 'Failed to fetch service versions';
          this.versionList = {};
          this.metadata = response.metadata || null;

          // Still add web_app version with health
          this.versionList.web_app = {
            success: true,
            version: this.app_version,
            deployed: process.env.DEPLOYMENT_TIME || '-',
            channel: currentChannel(),
            health: webAppHealth,
          };

          notify.error(
            `Failed to load service versions: ${this.errorMessage}`
          );
          return;
        }

        // Success - store versions and metadata
        this.versionList = response.versions || {};
        this.metadata = response.metadata || null;

        // Add web_app version with health
        this.versionList.web_app = {
          success: true,
          version: this.app_version,
          deployed: process.env.DEPLOYMENT_TIME || '-',
          channel: currentChannel(),
          health: webAppHealth,
        };

        // Show notification if some services failed
        if (this.metadata && this.metadata.failed > 0) {
          notify.warning(
            `Loaded ${this.metadata.successful}/${this.metadata.total_services} services. ${this.metadata.failed} failed.`
          );
        }
      } catch (err) {
        this.loadError = true;
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        this.errorMessage = msg;
        notify.error(msg);
        logError(err);

        // Still add web_app version on error
        this.versionList = {
          web_app: {
            success: true,
            version: this.app_version,
            deployed: process.env.DEPLOYMENT_TIME || '-',
            channel: currentChannel(),
          },
        };
      } finally {
        this.loading = false;
      }
    },

    /**
     * Fetch web_app health status from /version.json
     * Returns the health object or undefined if fetch fails
     */
    async fetchWebAppHealth(): Promise<{ status: string; details: string; checked_at: string } | undefined> {
      try {
        const response = await fetch('/version.json', { cache: 'no-cache' });
        if (response.ok) {
          const data = await response.json();
          return data.health;
        }
      } catch {
        // Silently fail - health indicator just won't show
      }
      return undefined;
    },
    /**
     * Strip environment prefix from service key
     * e.g., 'dev-api' → 'api', 'stage-extraction' → 'extraction'
     */
    stripEnvPrefix(key: string): string {
      if (!key) return '';
      const envPrefixes = ['dev-', 'stage-', 'sandbox-', 'demo-', 'prod-'];
      const lowerKey = key.toLowerCase();
      for (const prefix of envPrefixes) {
        if (lowerKey.startsWith(prefix)) {
          return key.substring(prefix.length);
        }
      }
      return key;
    },

    /**
     * Get shortened display name for a service
     * Falls back to formatted name if no mapping exists
     */
    getDisplayName(key: string): string {
      const stripped = this.stripEnvPrefix(key);
      const lowerKey = stripped.toLowerCase();

      // Check direct mapping first
      if (SERVICE_DISPLAY_NAMES[lowerKey]) {
        return SERVICE_DISPLAY_NAMES[lowerKey];
      }

      // Fallback to existing formatting
      return this.formatTextAndTranslate(stripped, '-', '_');
    },

    /**
     * Get health status icon based on status string
     * @param status - "healthy" | "degraded" | "unhealthy" | "unknown" | "starting"
     */
    getHealthIcon(status: string | undefined): string {
      const icons: Record<string, string> = {
        healthy: '🟢',
        degraded: '🟡',
        unhealthy: '🔴',
        unknown: '⚪',
        starting: '🔵',
      };
      return icons[status || 'unknown'] || '⚪';
    },

    /**
     * Get tooltip text for health status
     * @param health - Health object with status, details, and checked_at fields
     */
    getHealthTooltip(health: { status?: string; details?: string; checked_at?: string } | undefined): string {
      if (!health) return 'Health status unknown';

      const statusText = health.details || health.status || 'Unknown status';
      const timeText = health.checked_at
        ? ` (checked: ${this.formatTime(health.checked_at)})`
        : '';

      return `${statusText}${timeText}`;
    },

    /**
     * Format ISO timestamp to readable time
     * @param isoTime - ISO 8601 timestamp
     */
    formatTime(isoTime: string): string {
      try {
        const date = new Date(isoTime);
        return date.toLocaleTimeString(undefined, {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
        });
      } catch {
        return isoTime;
      }
    },
  },
  setup() {
    return { getReleaseName };
  },
});
</script>

