.versions-scroll-area {
  max-height: calc(76vh - 50px);
}

.metadata-section {
  background-color: rgba(0, 0, 0, 0.05);
  border-radius: 4px;

  .body--dark & {
    background-color: rgba(255, 255, 255, 0.05);
  }
}

.release-badge {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 4px;
}

.versions-table {
  // Remove any top margin/padding from table wrapper
  :deep(.docbits-table-wrapper),
  :deep(.docbits-table-container) {
    margin-top: 0;
    padding-top: 0;
  }

  :deep(.q-table) {
    // Compact styling for popup
    td, th {
