    }
  }

  // Remove the default height class that causes white space
  :deep(.q-table__container) {
    height: auto !important;
    max-height: none !important;
  }

  :deep(.q-table__middle) {
    height: auto !important;
  }

  // Hide skeleton loading container - not needed for this simple table
  :deep(.skeleton-loading-container) {
