/**
 * Key for MainLayout's <router-view>. Most routes key on fullPath, so a query
 * change remounts the page. /settings and /workflowsdashboard own their in-page
 * navigation (sub-paths / `?tab=`), so they key on a stable string to avoid
 * remounting (and the visible reload flash) on every such change.
 */
export function resolveRouteLayoutKey(path: string, fullPath: string): string {
  if (path.startsWith('/settings')) return 'settings-layout';
  if (path === '/workflowsdashboard') return 'workflowsdashboard';
  return fullPath;
}
