<script lang="ts">
import { Dark } from 'quasar';
import { useTolgee } from '@tolgee/vue';
import { storeToRefs } from 'pinia';
import { LocalStorage } from 'quasar';
import { defineComponent, ref, computed } from 'vue';
import { SUPPORT_URL, DOC2API_URL } from 'src/pages/APIs';
import { resolveRouteLayoutKey } from 'src/layouts/routeLayoutKey';
import { whenRegionReady } from 'src/pages/api-base-url';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
// import Footer from 'src/layouts/Footer.vue';
import helperMixin from '../mixins/helperMixin.js';
import { dark_mode_setting } from 'src/constants';
import SideMenu from 'src/components/LayoutHeader/SideMenu.vue';
import QuickSearchModal from 'src/components/QuickSearch/QuickSearchModal.vue';
import PerformanceAnalysisDialog from 'src/components/PerformanceAnalysisDialog.vue';
// Disabled: OfflineOverlay.vue provides better UX with center modal
// import ConnectionStatusIndicator from 'src/components/ConnectionStatus/ConnectionStatusIndicator.vue';
import {
  useDropdownStore,
  useUserFontSizeStore,
  useSettingStore,
} from 'src/store/main';
// import AccountSettingDropdown from 'src/components/LayoutHeader/AccountDropdown/main.vue';
export default defineComponent({
  name: 'MainLayout',
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.setDarkMode();
        }
      },
    },
  },
  unmounted() {
    document.removeEventListener('keydown', this.sendBack);
    document.removeEventListener('openPerformanceAnalysis', this.openPerfDialog);
  },
  mounted: function () {
    document.addEventListener('keydown', this.sendBack);
    document.addEventListener('openPerformanceAnalysis', this.openPerfDialog);
    this.fillDocTypeAndSubTypesListIfEmpty();
    this.initFontSize();
    this.init();
    this.prewarmDashboardBackend();
    if (process.env.APP_VUE_CURRENT_VERSION) {
      this.app_version = process.env.APP_VUE_CURRENT_VERSION
        ? process.env.APP_VUE_CURRENT_VERSION.toString()
        : '0.0.0';
    }
  },
  computed: {
    routeLayoutKey(): string {
      return resolveRouteLayoutKey(this.$route.path, this.$route.fullPath);
    },
  },
  methods: {
    isDashboardRoute() {
      return (
        this.$route.fullPath == '/dashboard' ||
        this.$route.fullPath == '/supplier/dashboard'
      );
    },
    navigateTo(route: string) {
      if (!route) return;
      this.$router.push(route);
    },
    init() {
      this.setDarkMode();
      // locale is already a computed that derives from tolgee.getLanguage()
      // No need to manually assign - it updates automatically
    },
    /**
     * Fire-and-forget POST /document/warmup. Fills backend
     * org-preferences + column-config + overview-stats caches so the
     * user's first dashboard query doesn't pay the ~1.5-2s cold-cache
     * cost.
     *
     * Runs once per browser session (guarded by sessionStorage so
     * navigating between layouts doesn't re-fire it). Any failure is
     * swallowed — this is a pure optimisation, never a gate.
     */
    async prewarmDashboardBackend() {
      if (sessionStorage.getItem('dashboard_warmup_fired') === '1') {
        return;
      }
      sessionStorage.setItem('dashboard_warmup_fired', '1');
      try {
        const authStore = useAuthTokenStore();
        const token = await authStore.getValidatedToken();
        if (!token) {
          return;
        }
        await whenRegionReady();
        fetch(`${DOC2API_URL}/document/warmup`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        }).catch(() => {
          // Swallow — warmup is best-effort. If the endpoint doesn't
          // exist yet (older backend) the first real dashboard query
          // just pays the cold-cache cost as before.
        });
      } catch {
        // Never let warmup break the UI.
      }
    },
    sendBack(event: any) {
      // document has q-dialog element
      if (event.key !== 'Escape' || document.querySelector('.q-dialog')) {
        return;
      }
      if (this.$route.path != '/dashboard') {
        this.$router.go(-1);
      }
    },
    setDarkMode() {
      const darkMode = this.user_settings[this.dark_mode_setting]
        ? true
        : false;
      if (darkMode) {
        this.$q.dark.set(true);
      }
      Dark.set(darkMode);
    },
    goHome() {
      this.$router.push('/dashboard');
    },
    supportIntegration() {
      this.$router.push('/support');
    },
    gotoSettings() {
      this.$router.push('/settings');
    },
    gotoReport() {
      this.$router.push('/report');
    },

    gotoCloud() {
      this.$router.push('/dashboard');
    },
    gotoWorkflow() {
      this.$router.push('/workflowsdashboard');
    },
    openPerfDialog() {
      this.showPerformanceDialog = true;
    },
  },
  data() {
    return {
      showIcons: false,
      supportURL: SUPPORT_URL,
      dark_mode_setting,
      showPerformanceDialog: false,
    };
  },
  components: {
    // Footer,
    SideMenu,
    QuickSearchModal,
    PerformanceAnalysisDialog,
    // Notifications,
    // AccountSettingDropdown,
    // Disabled: OfflineOverlay.vue provides better UX
    // ConnectionStatusIndicator,
  },
  mixins: [helperMixin],

  setup() {
    const tolgee = useTolgee(['language']);
    const locale = computed(() => tolgee.value.getLanguage() || 'en');

    const dropdown_store = useDropdownStore();
    const { fillDocTypeAndSubTypesListIfEmpty, getSelectedLanguage } =
      dropdown_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);

    const user_font_size_store = useUserFontSizeStore();
    const { initFontSize } = user_font_size_store;

    return {
      fillDocTypeAndSubTypesListIfEmpty,
      getSelectedLanguage,
      initFontSize,
      user_settings,
      settings_store,
      loading_settings,
      report: ref(true),
      app_version: ref('0.0.0'),
      locale,
      drawer: ref(true),
      miniState: ref(false),
      mode: ref('dashboard'),
    };
  },
});
</script>

