<template>
  <q-dialog
    v-model="isOpen"
    position="top"
    transition-show="fade"
    transition-hide="fade"
    :no-refocus="true"
    no-esc-dismiss
  >
    <div class="quick-search-dialog" ref="dialogContent">
      <!-- Search Input -->
      <div class="qs-search-row">
        <Icon icon="mdi:magnify" class="qs-search-icon" />
        <!-- Doc Type Picker Mode: show breadcrumb + filter -->
        <template v-if="pickerEntry">
          <span class="qs-picker-breadcrumb" @click="exitPicker">{{ pickerEntry.label }}</span>
          <Icon icon="mdi:chevron-right" class="qs-picker-sep" />
          <input
            ref="pickerInput"
            v-model="pickerFilter"
            type="text"
            :placeholder="pickerMode === 'doc_type' ? $t('qs_placeholder_select_doc_type') : $t('qs_placeholder_paste_doc_id')"
            class="qs-search-input"
            @keydown.down.prevent="moveSelection(1)"
            @keydown.up.prevent="moveSelection(-1)"
            @keydown.enter.prevent="openSelectedDocType"
            @keydown.escape.stop.prevent="exitPicker"
            @keydown.backspace="onPickerBackspace"
          />
        </template>
        <!-- Normal Search Mode -->
        <template v-else>
          <input
            ref="searchInput"
            v-model="query"
            type="text"
            :placeholder="$t('search_all_pages')"
            class="qs-search-input"
            @keydown.down.prevent="moveSelection(1)"
            @keydown.up.prevent="moveSelection(-1)"
            @keydown.enter.prevent="openSelected"
            @keydown.escape.prevent="close"
          />
        </template>
        <kbd class="qs-shortcut">ESC</kbd>
      </div>

      <!-- Picker Results: Doc Type -->
      <div class="qs-results" v-if="pickerEntry && pickerMode === 'doc_type'">
        <div
          v-for="(dt, index) in filteredDocTypes"
          :key="dt.value"
          class="qs-result-item"
          :class="{ selected: index === selectedIndex }"
          @click="selectDocType(dt.value)"
          @mouseenter="selectedIndex = index"
        >
          <div class="qs-result-icon">
            <Icon icon="mdi:file-document-outline" class="size-4" />
          </div>
          <div class="qs-result-content">
            <span class="qs-result-label">{{ dt.label }}</span>
            <span class="qs-result-category">{{ dt.value }}</span>
          </div>
          <Icon icon="mdi:chevron-right" class="qs-result-arrow" />
        </div>
        <div v-if="filteredDocTypes.length === 0" class="qs-empty">
          <span class="qs-empty-text">{{ $t('qs_no_document_types') }}</span>
        </div>
      </div>

      <!-- Picker Results: Document ID -->
      <div class="qs-results" v-else-if="pickerEntry && (pickerMode === 'doc_id' || pickerMode === 'deep_link_doc')">
        <!-- Paste ID action -->
        <div
          v-if="pickerFilter.trim()"
          class="qs-result-item"
          :class="{ selected: selectedIndex === 0 }"
          @click="selectDocId(pickerFilter.trim())"
          @mouseenter="selectedIndex = 0"
        >
          <div class="qs-result-icon">
            <Icon icon="mdi:arrow-right-circle-outline" class="size-4" />
          </div>
          <div class="qs-result-content">
            <span class="qs-result-label">{{ $t('qs_open_with_id', { id: pickerFilter.trim() }) }}</span>
            <span class="qs-result-category">{{ $t('qs_press_enter_navigate') }}</span>
          </div>
          <Icon icon="mdi:chevron-right" class="qs-result-arrow" />
        </div>
        <!-- Dashboard documents -->
        <div class="qs-section-label">{{ $t('qs_dashboard_documents') }}</div>
        <div
          v-for="(doc, index) in filteredDashboardDocs"
          :key="doc.id"
          class="qs-result-item"
          :class="{ selected: (pickerFilter.trim() ? index + 1 : index) === selectedIndex }"
          @click="selectDocId(doc.id)"
          @mouseenter="selectedIndex = pickerFilter.trim() ? index + 1 : index"
        >
          <div class="qs-result-icon">
            <Icon icon="mdi:file-outline" class="size-4" />
          </div>
          <div class="qs-result-content">
            <span class="qs-result-label">{{ doc.filename || doc.id }}</span>
            <span class="qs-result-category">{{ doc.doc_type }} &middot; {{ doc.status }} &middot; {{ doc.id.substring(0, 8) }}...</span>
          </div>
          <Icon icon="mdi:chevron-right" class="qs-result-arrow" />
        </div>
        <div v-if="filteredDashboardDocs.length === 0 && !pickerFilter.trim()" class="qs-empty">
          <span class="qs-empty-text">{{ $t('qs_no_documents_loaded') }}</span>
        </div>
      </div>

      <!-- Search Results -->
      <div class="qs-results" v-else-if="query.trim()">
        <div v-if="results.length === 0" class="qs-empty">
          <span class="qs-empty-text">{{ $t('qs_no_results', { query }) }}</span>
        </div>
        <template v-else>
          <div
            v-for="(result, index) in results"
            :key="result.entry.id"
            class="qs-result-item"
            :class="{ selected: index === selectedIndex }"
            @click="navigateToEntry(result.entry)"
            @mouseenter="selectedIndex = index"
          >
            <div class="qs-result-icon">
              <Icon :icon="result.entry.icon || 'mdi:file-outline'" class="size-4" />
            </div>
            <div class="qs-result-content">
              <span class="qs-result-label">{{ result.entry.label }}</span>
              <span class="qs-result-category">{{ categoryLabel(result.entry.category) }}</span>
            </div>
            <span
              v-if="result.entry.paramResolver && result.entry.paramResolver !== 'deep_link'"
              class="qs-result-type qs-result-type-resolver"
            >
              {{ $t('qs_select_type') }}
            </span>
            <span
              v-else-if="result.entry.type !== 'page'"
              class="qs-result-type"
            >
              {{ result.entry.type }}
            </span>
            <Icon
              v-if="result.entry.path"
              icon="mdi:chevron-right"
              class="qs-result-arrow"
            />
          </div>
        </template>
      </div>

      <!-- Recent / Hints when empty -->
      <div class="qs-results" v-else-if="recentSearches.length > 0">
        <div class="qs-section-label">{{ $t('qs_recent') }}</div>
        <div
          v-for="(recent, index) in recentSearches"
          :key="'recent-' + index"
          class="qs-result-item"
          @click="query = recent"
        >
          <Icon icon="mdi:history" class="qs-recent-icon" />
          <span class="qs-recent-text">{{ recent }}</span>
        </div>
      </div>

      <!-- Footer -->
      <div class="qs-footer">
        <span class="qs-footer-hint">
          <kbd class="qs-key">&#8593;</kbd>
          <kbd class="qs-key">&#8595;</kbd>
          {{ $t('qs_hint_navigate') }}
        </span>
        <span class="qs-footer-hint">
          <kbd class="qs-key">&#9166;</kbd>
          {{ $t('qs_hint_open') }}
        </span>
        <div class="qs-footer-right">
          <router-link
            v-if="query.trim()"
            :to="{ path: '/sitemap', query: { q: query } }"
            class="qs-view-all"
            @click="close"
          >
            {{ $t('qs_view_all_results') }}
          </router-link>
          <HelpLink name="global_quick_search" data-test="help-link-quick-search" class="qs-help" />
        </div>
      </div>
    </div>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useTranslate } from '@tolgee/vue';
import { search, type SearchResult } from 'src/utils/route-search';
import { isModuleRouteActive } from 'src/utils/module-access';
import { localizeRegistry, translateCategory, type IndexEntry } from 'src/utils/route-registry';
import { useDropdownStore, useDashboardStore } from 'src/store/main';
import { useSettingStore } from 'src/store/Settings/setting.store';

const RECENT_STORAGE_KEY = 'docbits_quick_search_recent';
const MAX_RECENT = 5;

export default defineComponent({
  name: 'QuickSearchModal',
  setup() {
    const dropdown_store = useDropdownStore();
    const { doc_type_list } = storeToRefs(dropdown_store);
    const dashboard_store = useDashboardStore();
    const { display_data } = storeToRefs(dashboard_store);
    const setting_store = useSettingStore();
    const { user_settings } = storeToRefs(setting_store);
    const { t } = useTranslate();
    return { doc_type_list, display_data, user_settings, t };
  },

  data() {
    return {
      isOpen: false,
      query: '',
      selectedIndex: 0,
      results: [] as SearchResult[],
      recentSearches: [] as string[],
      debounceTimer: null as ReturnType<typeof setTimeout> | null,
      pickerEntry: null as IndexEntry | null,
      pickerFilter: '',
    };
  },

  computed: {
    /** Registry with label/description in the active locale. Recomputes on language change. */
    localizedRegistry(): IndexEntry[] {
      return localizeRegistry((key, fallback) => this.t(key, fallback));
    },

    pickerMode(): string | null {
      if (!this.pickerEntry) return null;
      return this.pickerEntry.paramResolver || null;
    },

    filteredDocTypes(): any[] {
      const list = this.doc_type_list || [];
      if (!this.pickerFilter) return list;
      const q = this.pickerFilter.toLowerCase();
      return list.filter((dt: any) =>
        dt.label?.toLowerCase().includes(q) ||
        dt.value?.toLowerCase().includes(q),
      );
    },

    filteredDashboardDocs(): any[] {
      let docs = this.display_data || [];
      // Apply status filter from entry (e.g., approval only shows validated_pending_approval)
      if (this.pickerEntry?.statusFilter?.length) {
        const statuses = this.pickerEntry.statusFilter;
        docs = docs.filter((doc: any) => statuses.includes(doc.status));
      }
      if (!this.pickerFilter) return docs.slice(0, 20);
      const q = this.pickerFilter.toLowerCase();
      return docs.filter((doc: any) =>
        doc.filename?.toLowerCase().includes(q) ||
        doc.id?.toLowerCase().includes(q) ||
        doc.doc_type?.toLowerCase().includes(q),
      ).slice(0, 20);
    },
  },

  watch: {
    query(val: string) {
      this.selectedIndex = 0;
      if (this.debounceTimer) clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => {
        this.results = val.trim()
          ? this.activeResults(search(val, { maxResults: 8, registry: this.localizedRegistry }))
          : [];
      }, 100);
    },
    pickerFilter() {
      this.selectedIndex = 0;
    },
    isOpen(val: boolean) {
      if (val) {
        this.query = '';
        this.results = [];
        this.selectedIndex = 0;
        this.pickerEntry = null;
        this.pickerFilter = '';
        this.loadRecentSearches();
        this.$nextTick(() => {
          (this.$refs.searchInput as HTMLInputElement)?.focus();
        });
      }
    },
  },

  mounted() {
    document.addEventListener('keydown', this.handleGlobalKeydown);
    this.loadRecentSearches();
  },

  unmounted() {
    document.removeEventListener('keydown', this.handleGlobalKeydown);
    if (this.debounceTimer) clearTimeout(this.debounceTimer);
  },

  methods: {
    categoryLabel(category: string): string {
      return translateCategory(category, (key, fallback) => this.t(key, fallback));
    },

    open() {
      this.isOpen = true;
    },

    close() {
      this.isOpen = false;
    },

    activeResults(results: SearchResult[]): SearchResult[] {
      return results.filter((result) =>
        isModuleRouteActive(result.entry.path, this.user_settings),
      );
    },

    handleGlobalKeydown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        this.isOpen = !this.isOpen;
      }
    },

    moveSelection(delta: number) {
      let listLen: number;
      if (this.pickerMode === 'doc_type') {
        listLen = this.filteredDocTypes.length;
      } else if (this.pickerMode === 'doc_id' || this.pickerMode === 'deep_link_doc') {
        listLen = this.filteredDashboardDocs.length + (this.pickerFilter.trim() ? 1 : 0);
      } else {
        listLen = this.results.length;
      }
      if (listLen === 0) return;
      this.selectedIndex = Math.max(
        0,
        Math.min(listLen - 1, this.selectedIndex + delta),
      );
      // Scroll selected item into view
      this.$nextTick(() => {
        const dialogEl = this.$refs.dialogContent as HTMLElement;
        if (!dialogEl) return;
        const selected = dialogEl.querySelector('.qs-result-item.selected') as HTMLElement;
        if (selected) {
          selected.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
        }
      });
    },

    openSelected() {
      if (this.results.length > 0 && this.selectedIndex < this.results.length) {
        this.navigateToEntry(this.results[this.selectedIndex].entry);
      }
    },

    openSelectedDocType() {
      const mode = this.pickerMode;
      if (mode === 'doc_type') {
        if (this.filteredDocTypes.length > 0 && this.selectedIndex < this.filteredDocTypes.length) {
          this.selectDocType(this.filteredDocTypes[this.selectedIndex].value);
        }
      } else if (mode === 'doc_id' || mode === 'deep_link_doc') {
        // If filter has text, index 0 = "Open with ID" action
        if (this.pickerFilter.trim() && this.selectedIndex === 0) {
          this.selectDocId(this.pickerFilter.trim());
        } else {
          const offset = this.pickerFilter.trim() ? 1 : 0;
          const docIndex = this.selectedIndex - offset;
          if (docIndex >= 0 && docIndex < this.filteredDashboardDocs.length) {
            this.selectDocId(this.filteredDashboardDocs[docIndex].id);
          }
        }
      }
    },

    /** Enter picker mode for an entry */
    enterPicker(entry: IndexEntry) {
      this.pickerEntry = entry;
      this.pickerFilter = '';
      this.selectedIndex = 0;
      this.$nextTick(() => {
        (this.$refs.pickerInput as HTMLInputElement)?.focus();
      });
    },

    /** Exit doc type picker, return to search results */
    exitPicker() {
      this.pickerEntry = null;
      this.pickerFilter = '';
      this.selectedIndex = 0;
      this.$nextTick(() => {
        (this.$refs.searchInput as HTMLInputElement)?.focus();
      });
    },

    onPickerBackspace() {
      if (!this.pickerFilter) {
        this.exitPicker();
      }
    },

    /** Select a doc type and navigate */
    selectDocType(docTypeKey: string) {
      const entry = this.pickerEntry;
      if (!entry?.path || !entry.paramResolverTarget) return;

      if (this.query.trim()) {
        this.saveRecentSearch(this.query.trim());
      }

      let resolvedPath = entry.path;
      resolvedPath = resolvedPath.replace(`:${entry.paramResolverTarget}`, docTypeKey);
      resolvedPath = resolvedPath.replace(/\/:[^/]+\?/g, '');
      resolvedPath = resolvedPath.replace(/\/:[^/]+/g, '');

      this.$router.push(resolvedPath);
      this.close();
    },

    /** Select a document ID and navigate */
    selectDocId(docId: string) {
      const entry = this.pickerEntry;
      if (!entry) return;

      if (this.query.trim()) {
        this.saveRecentSearch(this.query.trim());
      }

      if (entry.paramResolver === 'deep_link_doc') {
        // Navigate to host page with ?open=action&doc_id=id
        const path = entry.deepLinkPath || '/dashboard';
        this.$router.push({
          path,
          query: { open: entry.deepLinkAction, doc_id: docId },
        });
      } else {
        // doc_id resolver — replace :id in path
        if (!entry.path || !entry.paramResolverTarget) return;
        let resolvedPath = entry.path;
        resolvedPath = resolvedPath.replace(`:${entry.paramResolverTarget}`, docId);
        resolvedPath = resolvedPath.replace(/\/:[^/]+\?/g, '');
        resolvedPath = resolvedPath.replace(/\/:[^/]+/g, '');
        this.$router.push(resolvedPath);
      }

      this.close();
    },

    navigateToEntry(entry: IndexEntry) {
      if (this.query.trim()) {
        this.saveRecentSearch(this.query.trim());
      }

      // deep_link: navigate to host page with ?open= query param (no picker)
      if (entry.paramResolver === 'deep_link' && entry.deepLinkPath) {
        const query: Record<string, string> = {};
        let basePath = entry.deepLinkPath;
        // Parse existing query params from deepLinkPath (e.g., /settings/watchdog?tab=configurations)
        if (basePath.includes('?')) {
          const [p, qs] = basePath.split('?');
          basePath = p;
          new URLSearchParams(qs).forEach((v, k) => { query[k] = v; });
        }
        if (entry.deepLinkAction) query.open = entry.deepLinkAction;
        this.$router.push({ path: basePath, query });
        this.close();
        return;
      }

      // Entries that need a picker (doc_type, doc_id, deep_link_doc)
      if (entry.paramResolver === 'doc_type' || entry.paramResolver === 'doc_id' || entry.paramResolver === 'deep_link_doc') {
        this.enterPicker(entry);
        return;
      }

      if (entry.path) {
        // Handle query param paths like /workflowsdashboard?tab=workflowlist
        if (entry.path.includes('?')) {
          const [path, qs] = entry.path.split('?');
          const query: Record<string, string> = {};
          new URLSearchParams(qs).forEach((v, k) => { query[k] = v; });
          this.$router.push({ path, query });
          this.close();
          return;
        }

        const cleanPath = entry.path.replace(/\/:[^/]+\??/g, '');
        if (cleanPath && cleanPath !== entry.path) {
          // Has required params but no resolver — go to sitemap
          this.$router.push({ path: '/sitemap', query: { q: entry.label } });
        } else {
          this.$router.push(entry.path);
        }
      } else {
        // In-page feature — go to sitemap with search
        this.$router.push({ path: '/sitemap', query: { q: entry.label } });
      }

      this.close();
    },

    loadRecentSearches() {
      try {
        const stored = localStorage.getItem(RECENT_STORAGE_KEY);
        this.recentSearches = stored ? JSON.parse(stored) : [];
      } catch {
        this.recentSearches = [];
      }
    },

    saveRecentSearch(query: string) {
      this.recentSearches = [
        query,
        ...this.recentSearches.filter((r) => r !== query),
      ].slice(0, MAX_RECENT);

      try {
        localStorage.setItem(RECENT_STORAGE_KEY, JSON.stringify(this.recentSearches));
      } catch {
        // localStorage full — ignore
      }
    },
  },
});
</script>

